  "content": "(function(){
  const pageSlug = 'reminder';
  window.ForgeAI.registerPage(pageSlug, async function(ctx) {
    const root = ctx.root;
    root.innerHTML = '';

    // Header
    const header = document.createElement('div');
    header.className = 'page-header';
    const title = document.createElement('h2');
    title.textContent = 'Reminders';
    header.appendChild(title);
    const addBtn = document.createElement('button');
    addBtn.textContent = 'Add Reminder';
    addBtn.className = 'btn btn-primary';
    header.appendChild(addBtn);
    root.appendChild(header);

    // Table container
    const table = document.createElement('table');
    table.className = 'reminder-table';
    root.appendChild(table);

    // Toast helper
    function showToast(message, type = 'info') {
      const toast = document.createElement('div');
      toast.className = 'toast toast-' + type;
      toast.textContent = message;
      document.body.appendChild(toast);
      setTimeout(() => toast.remove(), 3000);
    }

    // Load reminders from API
    async function loadReminders() {
      try {
        const resp = await ctx.api('/api/reminders', { method: 'GET' });
        if (resp && resp.success) {
          return resp.data || [];
        }
        showToast('Failed to load reminders.', 'error');
        return [];
      } catch (e) {
        showToast('Error loading reminders.', 'error');
        return [];
      }
    }

    // Render table rows
    function renderTable(reminders) {
      table.innerHTML = '';
      const thead = document.createElement('thead');
      const headerRow = document.createElement('tr');
      ['Date', 'Type', 'Message'].forEach(text => {
        const th = document.createElement('th');
        th.textContent = text;
        headerRow.appendChild(th);
      });
      thead.appendChild(headerRow);
      table.appendChild(thead);

      const tbody = document.createElement('tbody');
      if (reminders.length === 0) {
        const emptyRow = document.createElement('tr');
        const td = document.createElement('td');
        td.colSpan = 3;
        td.className = 'empty-state';
        td.textContent = 'No reminders yet. Click "Add Reminder" to create one.';
        emptyRow.appendChild(td);
        tbody.appendChild(emptyRow);
      } else {
        reminders.forEach(r => {
          const tr = document.createElement('tr');
          const tdDate = document.createElement('td');
          tdDate.textContent = r.date;
          const tdType = document.createElement('td');
          tdType.textContent = r.type;
          const tdMsg = document.createElement('td');
          tdMsg.textContent = r.message;
          [tdDate, tdType, tdMsg].forEach(td => tr.appendChild(td));
          tbody.appendChild(tr);
        });
      }
      table.appendChild(tbody);
    }

    // Refresh data
    async function refresh() {
      const data = await loadReminders();
      renderTable(data);
    }

    // Modal for adding a reminder
    function openAddModal() {
      // Overlay
      const overlay = document.createElement('div');
      overlay.className = 'modal-overlay';
      // Modal box
      const modal = document.createElement('div');
      modal.className = 'modal';

      const form = document.createElement('form');
      form.innerHTML = `
        <h3>Add Reminder</h3>
        <label>Date</label>
        <input type="date" name="date" required />
        <label>Type</label>
        <input type="text" name="type" required />
        <label>Message</label>
        <textarea name="message" rows="3" required></textarea>
        <div class="modal-actions">
          <button type="submit" class="btn btn-primary">Save</button>
          <button type="button" class="btn btn-secondary">Cancel</button>
        </div>
      `;

      form.addEventListener('submit', async e => {
        e.preventDefault();
        const formData = new FormData(form);
        const payload = {
          date: formData.get('date'),
          type: formData.get('type'),
          message: formData.get('message')
        };
        try {
          const resp = await ctx.api('/api/reminders', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
          });
          if (resp && resp.success) {
            showToast('Reminder added.', 'success');
            overlay.remove();
            await refresh();
          } else {
            showToast('Failed to add reminder.', 'error');
          }
        } catch (err) {
          showToast('Error adding reminder.', 'error');
        }
      });

      const cancelBtn = form.querySelector('button[type="button"]');
      cancelBtn.addEventListener('click', () => overlay.remove());

      modal.appendChild(form);
      overlay.appendChild(modal);
      document.body.appendChild(overlay);
    }

    // Initial load
    await refresh();

    // Bind add button
    addBtn.addEventListener('click', openAddModal);
  });
})();
"
}
